// Bounded Frame Debugger inspection, separate from all timing probes.
using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class EnergyClusterFrameEvents {
 static BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;
 static string Out=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/EnergyCluster/V6");
 static Type utility,windowType;static EditorWindow window,focused;static bool created,background,paused;static List<GameObject> clones=new List<GameObject>(),hidden=new List<GameObject>();static List<bool> active=new List<bool>();static List<object> reports=new List<object>();static int count=1,stage,attempts;static double begin;
 static object Field(object obj,string name)=>obj.GetType().GetField(name,F)?.GetValue(obj);
 static void Disable(){windowType.GetMethod("DisableFrameDebugger",F).Invoke(window,null);EditorApplication.isPaused=false;}
 static void Setup(){foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);clones.Clear();for(int i=0;i<count;i++){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/EnergyCluster/Prefabs/VFX_EnergyCluster_Loop.prefab"));g.name="EnergyCluster_Frame_Temporary";clones.Add(g);}stage=0;begin=Time.timeAsDouble;}
 static void Finish(string error=null){EditorApplication.update-=Tick;try{Disable();}catch{}foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);for(int i=0;i<hidden.Count;i++)if(hidden[i]!=null)hidden[i].SetActive(active[i]);Application.runInBackground=background;EditorApplication.isPaused=paused;if(created&&window!=null)window.Close();if(focused!=null)focused.Focus();File.WriteAllText(Path.Combine(Out,"FrameDebuggerEvents.json"),JsonConvert.SerializeObject(new{error,method="Official FrameDebuggerWindow EnableFrameDebugger, real Play Mode 1/8 overlapping instances. Separate from performance timing.",reports,limitation="Metadata cannot prove exact renderer merges/break reasons unless native per-event detail is available.",restored=true},Formatting.Indented));}
 static void Tick(){try{if(!Application.isPlaying){Finish("Stopped externally");return;}
  if(stage==0&&Time.timeAsDouble-begin>.8){EditorApplication.isPaused=true;windowType.GetMethod("EnableFrameDebugger",F).Invoke(window,null);stage=1;begin=EditorApplication.timeSinceStartup;attempts=0;return;}
  if(stage==1&&EditorApplication.timeSinceStartup-begin>.7){var events=(Array)utility.GetMethod("GetFrameEvents",F).Invoke(null,null);if((events==null||events.Length==0)&&attempts++<2){begin=EditorApplication.timeSinceStartup;return;}var list=new List<object>();int details=0;if(events!=null)for(int i=0;i<events.Length;i++){var evt=events.GetValue(i);var obj=Field(evt,"m_Obj") as UnityEngine.Object;string type=Field(evt,"m_Type")?.ToString();if(type==null)continue;bool dataOk=false;object detail=null;if(obj!=null&&details++<5){try{var dt=typeof(Editor).Assembly.GetType("UnityEditorInternal.FrameDebuggerInternal.FrameDebuggerEventData");var data=Activator.CreateInstance(dt,true);dataOk=(bool)utility.GetMethod("GetFrameEventData",F).Invoke(null,new[]{(object)i,data});if(dataOk)detail=new{shader=Field(data,"m_RealShaderName")?.ToString(),pass=Field(data,"m_PassName")?.ToString(),draws=Field(data,"m_DrawCallCount"),instances=Field(data,"m_InstanceCount")};}catch{}}list.Add(new{index=i,type,obj=obj==null?null:obj.name,info=utility.GetMethod("GetFrameEventInfoName",F).Invoke(null,new object[]{i})?.ToString(),dataOk,detail});}
   reports.Add(new{instances=count,totalEvents=events?.Length??0,events=list,liveParticles=clones.Sum(g=>g.GetComponentsInChildren<ParticleSystem>().Sum(p=>p.particleCount))});Disable();if(count==1){count=8;Setup();}else Finish();}
 }catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets")throw new Exception("Wrong target/state");utility=typeof(Editor).Assembly.GetType("UnityEditorInternal.FrameDebuggerInternal.FrameDebuggerUtility");windowType=typeof(Editor).Assembly.GetType("UnityEditor.FrameDebuggerWindow");focused=EditorWindow.focusedWindow;background=Application.runInBackground;paused=EditorApplication.isPaused;Application.runInBackground=true;window=Resources.FindObjectsOfTypeAll(windowType).Cast<EditorWindow>().FirstOrDefault();created=window==null;if(created)window=EditorWindow.GetWindow(windowType);foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects().Where(g=>g.GetComponent<Camera>()==null)){hidden.Add(root);active.Add(root.activeSelf);root.SetActive(false);}Setup();EditorApplication.update+=Tick;return "Bounded 1/8 instance Frame Debugger probe scheduled.";}
}
